import fs from "node:fs";
import path from "node:path";

export type StaticDiagramProps = {
  /** Diagram file name without extension, e.g. "order-state-machine" for public/diagrams/order-state-machine.svg */
  name: string;
  caption?: string;
};

/**
 * Renders an SVG generated by the Python pipeline in scripts/diagrams/
 * (see docs/adr/0001-python-diagram-pipeline.md). Unlike MermaidDiagram,
 * this needs no client-side JS: the SVG is fixed at build time, so it is
 * read from public/diagrams/ and inlined directly in this Server Component.
 *
 * The SVG's own <style> block uses `var(--token)` colors (never literal
 * hex), so once inlined into the page DOM it resolves against the same
 * light/dark tokens as the rest of the site with no extra wiring here.
 */
export function StaticDiagram({ name, caption }: StaticDiagramProps) {
  const filePath = path.join(process.cwd(), "public", "diagrams", `${name}.svg`);
  let svg: string;
  try {
    svg = fs.readFileSync(filePath, "utf-8");
  } catch {
    return (
      <div className="my-10 rounded-2xl overflow-hidden bg-bg-elevated p-6 border border-theme-error/30">
        <p className="text-theme-error text-sm font-semibold">Diagram not found</p>
        <p className="mt-2 text-xs text-content-secondary">
          Expected public/diagrams/{name}.svg. Run <code>npm run diagrams</code> to generate it.
        </p>
      </div>
    );
  }

  return (
    <figure className="my-10">
      <div className="rounded-3xl overflow-hidden bg-bg-elevated shadow-neu-raised relative z-10">
        <div className="flex items-center justify-between px-6 py-4 rounded-t-3xl bg-bg-sunken shadow-neu-sunken-subtle">
          <div className="flex items-center gap-3">
            <div className="flex gap-1.5">
              <span className="w-2.5 h-2.5 rounded-full bg-content-muted/40" />
              <span className="w-2.5 h-2.5 rounded-full bg-content-muted/25" />
              <span className="w-2.5 h-2.5 rounded-full bg-content-muted/15" />
            </div>
            <span className="text-xs font-black uppercase tracking-[0.18em] font-mono text-content-secondary/80">
              Static diagram
            </span>
          </div>
        </div>

        <div
          role="region"
          aria-label="Diagram, scrollable horizontally"
          tabIndex={0}
          className="w-full overflow-x-auto overflow-y-hidden p-8 flex items-center justify-center min-h-[200px] bg-bg-elevated"
        >
          <div
            role="img"
            aria-label={caption ?? "Diagram"}
            className="[&>svg]:max-w-full [&>svg]:h-auto [&>svg]:min-w-0"
            dangerouslySetInnerHTML={{ __html: svg }}
          />
        </div>
      </div>

      {caption && (
        <figcaption className="mt-3 text-center text-sm font-medium text-content-secondary">
          {caption}
        </figcaption>
      )}
    </figure>
  );
}
